using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
namespace LumaDesk {
public static class EventListModel {
 public static List<Item> Select(IEnumerable<Item> items,string kind,DateTime? date){return items.Where(a=>a.Kind==kind&&(!date.HasValue||Host.MatchesDate(a,date.Value.Date))).OrderBy(a=>a.Next).ToList();}
 public static string Repeat(Item a){if(a.Days==0)return "Один раз";if(a.Days==127)return "Каждый день";if(a.Days==62)return "По будням";string[] names={"вс","пн","вт","ср","чт","пт","сб"};return string.Join(", ",Enumerable.Range(0,7).Select(i=>(i+1)%7).Where(i=>(a.Days&(1<<i))!=0).Select(i=>names[i]).ToArray());}
}
public static class EventListArt {
 public static void Frame(Graphics g,string kind,DateTime? date,bool empty,int height){bool alarm=kind=="alarm";EditorArt.T(g,alarm?"Будильники":"Напоминания",27,EditorArt.Text,24,24,true);EditorArt.T(g,date.HasValue?date.Value.ToString("d MMMM yyyy",Program.Ru):alarm?"Твой ритм дня":"Всё важное — в одном месте",12,EditorArt.Muted,26,65);using(var p=new Pen(AppTheme.Edge))g.DrawLine(p,24,96,596,96);if(empty){EditorArt.Box(g,new Rectangle(280,125,60,60),AppTheme.Panel,18);using(var p=new Pen(EditorArt.Accent,2)){g.DrawEllipse(p,298,141,24,24);g.DrawLine(p,310,147,310,154);g.DrawLine(p,310,154,316,158);}EditorArt.Center(g,alarm?"Пока нет будильников":"Здесь появятся твои напоминания",new Rectangle(20,203,580,27),19,EditorArt.Text,true);EditorArt.Center(g,alarm?"Выбери время и мелодию для первого сигнала":"Добавь событие — мы напомним о нём вовремя",new Rectangle(20,240,580,20),12,EditorArt.Muted);}EditorArt.T(g,empty?"Сигналы работают, пока программа запущена":"Нажми карточку, чтобы изменить событие",11,EditorArt.Muted,26,height-28);}
 static void FitText(Graphics g,string text,Rectangle rect,int size,Color color,bool bold=false){using(var f=new Font(Scene.FontName,size,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel))using(var b=new SolidBrush(color))using(var fmt=new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.NoWrap,LineAlignment=StringAlignment.Center})g.DrawString(text,f,b,rect,fmt);}
 public static void Row(Graphics g,Rectangle r,Item a,bool selected){EditorArt.Box(g,r,selected?AppTheme.Selection:AppTheme.Panel,10);Color main=a.Enabled?EditorArt.Text:EditorArt.Muted;EditorArt.T(g,a.Next.ToString("HH:mm"),28,main,r.X+18,r.Y+13,true);EditorArt.T(g,a.Next.ToString("dd MMM",Program.Ru),10,EditorArt.Muted,r.X+20,r.Y+54);using(var p=new Pen(AppTheme.Edge))g.DrawLine(p,r.X+126,r.Y+18,r.X+126,r.Y+66);FitText(g,a.Title,new Rectangle(r.X+145,r.Y+13,r.Width-237,25),14,main,true);FitText(g,EventListModel.Repeat(a)+"  ·  "+Melodies.Name(a.Sound),new Rectangle(r.X+145,r.Y+44,r.Width-237,22),10,EditorArt.Muted);
 EditorArt.Switch(g,new Rectangle(r.Right-70,r.Y+17,48,24),a.Enabled);using(var p=new Pen(EditorArt.Muted,1.4f)){int x=r.Right-64,y=r.Y+57;g.DrawLine(p,x,y+7,x+7,y);g.DrawLine(p,x+2,y+9,x+9,y+2);g.DrawLine(p,x,y+7,x,y+10);g.DrawLine(p,x,y+10,x+2,y+9);int bx=r.Right-32;g.DrawLine(p,bx-4,y,bx+6,y);g.DrawRectangle(p,bx-2,y+3,7,8);g.DrawLine(p,bx,y-2,bx+3,y-2);}}
}
public class EventRows:SmoothControl {
 public List<Item> Items=new List<Item>();public Action<Item> EditItem,ToggleItem,DeleteItem;int offset,selection=-1;const int RowHeight=94;
 public EventRows(Rectangle bounds){Bounds=bounds;AccessibleName="Список событий";AccessibleRole=AccessibleRole.List;MouseClick+=(s,e)=>{int index=(e.Y+offset)/RowHeight;if(index<0||index>=Items.Count||(e.Y+offset)%RowHeight>=84)return;selection=index;Focus();if(e.X>Width-80&&((e.Y+offset)%RowHeight)<47){if(ToggleItem!=null)ToggleItem(Items[index]);}else if(e.X>Width-43){if(DeleteItem!=null)DeleteItem(Items[index]);}else if(EditItem!=null)EditItem(Items[index]);Invalidate();};}
 public void Reset(List<Item> items){Items=items;offset=Math.Min(offset,Math.Max(0,Items.Count*RowHeight-Height));selection=Math.Min(selection,items.Count-1);Invalidate();}
 protected override void OnMouseWheel(MouseEventArgs e){offset=Math.Max(0,Math.Min(Math.Max(0,Items.Count*RowHeight-Height),offset-e.Delta/120*48));Invalidate();base.OnMouseWheel(e);}
 protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Down||e.KeyCode==Keys.Up){selection=Math.Max(0,Math.Min(Items.Count-1,selection+(e.KeyCode==Keys.Down?1:-1)));if(selection>=0){if(selection*RowHeight<offset)offset=selection*RowHeight;if(selection*RowHeight+84>offset+Height)offset=selection*RowHeight+84-Height;}Invalidate();e.Handled=true;}else if(selection>=0&&selection<Items.Count){if(e.KeyCode==Keys.Delete){if(DeleteItem!=null)DeleteItem(Items[selection]);e.Handled=true;}else if(e.KeyCode==Keys.Space){if(ToggleItem!=null)ToggleItem(Items[selection]);e.Handled=true;}else if(e.KeyCode==Keys.Enter){if(EditItem!=null)EditItem(Items[selection]);e.Handled=true;}}if(!e.Handled)base.OnKeyDown(e);}
 protected override void Draw(Graphics g){for(int i=0;i<Items.Count;i++){int y=i*RowHeight-offset;if(y+84<0||y>=Height)continue;EventListArt.Row(g,new Rectangle(0,y,Width-10,84),Items[i],i==selection);}if(Items.Count*RowHeight>Height){int thumb=Math.Max(26,(int)(Height*(double)Height/(Items.Count*RowHeight)));int y=(int)((Height-thumb)*(double)offset/(Items.Count*RowHeight-Height));EditorArt.Box(g,new Rectangle(Width-4,y,3,thumb),Color.FromArgb(91,99,128),1);}}
}
public class EventListForm:ChromeForm {
 Host host;string kind;DateTime? date;EventRows rows;SmoothButton add,emptyAdd;int contentHeight;
 public EventListForm(Host app,string eventKind,DateTime? filter){host=app;kind=eventKind;date=filter;Text=kind=="alarm"?"Будильники":"Напоминания";SetContentSize(620,350);rows=new EventRows(new Rectangle(24,115,572,316));rows.EditItem=a=>{host.Edit(a,kind,null);Reload();};rows.ToggleItem=a=>{if(!a.Enabled&&a.Next<=DateTime.Now){if(a.Days==0){host.Edit(a,kind,null);Reload();return;}a.Next=Host.Advance(a,DateTime.Now);}a.Enabled=!a.Enabled;Store.Save();Reload();};rows.DeleteItem=a=>Delete(a);Controls.Add(rows);add=new SmoothButton("+  Добавить",new Rectangle(420,25,176,40),(s,e)=>Add()){Primary=true};emptyAdd=new SmoothButton(kind=="alarm"?"+  Создать будильник":"+  Добавить напоминание",new Rectangle(180,284,260,42),(s,e)=>Add()){Primary=true};Controls.Add(add);Controls.Add(emptyAdd);Reload();}
 void Add(){host.Edit(null,kind,date);Reload();}
 void Reload(){var items=EventListModel.Select(Store.S.Items,kind,date);rows.Reset(items);bool empty=items.Count==0;contentHeight=empty?365:473;SetContentSize(620,contentHeight);rows.Visible=!empty;add.Visible=!empty;emptyAdd.Visible=empty;Invalidate();}
 void Delete(Item item){using(var dialog=new ChromeForm("Удалить событие",430,210)){dialog.Controls.Add(new Label{Text="Удалить событие?",Font=Theme.F(16,FontStyle.Bold),ForeColor=EditorArt.Text,Bounds=new Rectangle(24,24,380,40)});dialog.Controls.Add(new Label{Text=item.Title,AutoEllipsis=true,ForeColor=EditorArt.Muted,Bounds=new Rectangle(24,74,380,42)});dialog.Controls.Add(new SmoothButton("Оставить",new Rectangle(24,142,180,40),(s,e)=>{dialog.DialogResult=DialogResult.Cancel;dialog.Close();}));dialog.Controls.Add(new SmoothButton("Удалить",new Rectangle(216,142,190,40),(s,e)=>{dialog.DialogResult=DialogResult.OK;dialog.Close();}){Primary=true});if(dialog.ShowDialog(this)==DialogResult.OK){Store.S.Items.Remove(item);Store.Save();Reload();}}}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var save=e.Graphics.Save();e.Graphics.TranslateTransform(0,CaptionHeight);e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;e.Graphics.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;EventListArt.Frame(e.Graphics,kind,date,rows==null||rows.Items.Count==0,contentHeight);e.Graphics.Restore(save);}
}
}
